sp_widget.client_script:
api.controller = function($scope, $interval, $timeout) {
  var c = this;

  // INIT
  c.data.fileName = '';
  c.data.processing = false;
  c.data.result = null;
  c.data.error = null;
  c.data.sysId = null;
  c.data.statusMsg = '';
  c.dragging = false;
  c.rawFile = null;

  var pollTimer = null;
  var pollCount = 0;
  var MAX_POLLS = 36;

  // FILE SELECT
  c.triggerUpload = function() {
    document.getElementById('ocrFileInput').click();
  };

  c.onFileSelect = function(event) {
    var file = event.target.files[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      c.data.error = 'Please select a valid PDF file.';
      return;
    }

    c.rawFile = file;
    c.data.fileName = file.name;
    c.data.error = null;
  };

  // DRAG DROP
  c.onDragOver = function(e) {
    e.preventDefault();
    c.dragging = true;
  };

  c.onDrop = function(e) {
    e.preventDefault();
    c.dragging = false;

    var file = e.dataTransfer.files[0];
    if (!file || file.type !== 'application/pdf') {
      c.data.error = 'Please drop a valid PDF file.';
      return;
    }

    c.rawFile = file;
    c.data.fileName = file.name;
  };

  // PROCESS DOCUMENT
  c.processDocument = function() {
    if (!c.rawFile) return;

    c.data.processing = true;
    c.data.statusMsg = 'Creating record...';
    c.data.error = null;

    // ✅ CORRECT WAY
    c.data.action = 'create_record';

    c.server.update().then(function(response) {

      if (response.data.serverError) {
        c.data.processing = false;
        c.data.error = response.data.serverError;
        return;
      }

      c.data.sysId = response.data.sysId;

      if (!c.data.sysId) {
        c.data.processing = false;
        c.data.error = 'Record not created.';
        return;
      }

      c.data.statusMsg = 'Uploading PDF...';
      c.uploadViaApi(c.rawFile, c.data.sysId);
    });
  };

  // UPLOAD ATTACHMENT
  c.uploadViaApi = function(file, sysId) {

    var url = '/api/now/attachment/file'
      + '?table_name=x_birl3_clm_ocr_test'
      + '&table_sys_id=' + sysId
      + '&file_name=' + encodeURIComponent(file.name);

    var xhr = new XMLHttpRequest();
    xhr.open('POST', url, true);

    xhr.setRequestHeader('Content-Type', 'application/pdf');
    xhr.setRequestHeader('Accept', 'application/json');
    xhr.setRequestHeader('X-UserToken', window.g_ck);

    xhr.onload = function() {

      console.log("UPLOAD RESPONSE:", xhr.responseText);

      if (xhr.status === 200 || xhr.status === 201) {

        $timeout(function() {
          c.data.statusMsg = 'Document uploaded. Running OCR...';

          // ⏳ Wait for attachment indexing
          $timeout(function() {
            c.startPolling();
          }, 3000);

        });

      } else {
        $timeout(function() {
          c.data.processing = false;
          c.data.error = 'Upload failed: ' + xhr.responseText;
        });
      }
    };

    xhr.onerror = function() {
      $timeout(function() {
        c.data.processing = false;
        c.data.error = 'Network error during upload.';
      });
    };

    xhr.send(file);
  };

  // POLLING
  c.startPolling = function() {
    pollCount = 0;

    pollTimer = $interval(function() {
      pollCount++;

      c.server.get({
        action: 'poll',
        sysId: c.data.sysId
      }).then(function(response) {

        if (response.data.result) {
          $interval.cancel(pollTimer);
          c.data.processing = false;
          c.data.result = response.data.result;

        } else if (pollCount >= MAX_POLLS) {
          $interval.cancel(pollTimer);
          c.data.processing = false;
          c.data.error = 'OCR timeout after 6 minutes.';
        } else {
          c.data.statusMsg = 'Processing OCR... (' + (pollCount * 10) + 's)';
        }
      });

    }, 10000);
  };

  // SUMMARY SPLIT
  c.getSummaryPoints = function(summary) {
    if (!summary) return [];

    var parts = summary.split(/\s*-\s*/);
    var result = [];

    parts.forEach(function(p) {
      p = p.trim().replace(/^•\s*/, '');
      if (p.length > 3) result.push(p);
    });

    return result;
  };

  // RISK COLOR
  c.getRiskClass = function(risk) {
    if (!risk) return '';
    risk = risk.toLowerCase();

    if (risk.includes('low')) return 'risk-low';
    if (risk.includes('high')) return 'risk-high';
    return 'risk-medium';
  };

  // RESET
  c.reset = function() {
    if (pollTimer) $interval.cancel(pollTimer);

    c.rawFile = null;
    c.data.fileName = '';
    c.data.processing = false;
    c.data.result = null;
    c.data.error = null;
    c.data.sysId = null;
  };

  $scope.$on('$destroy', function() {
    if (pollTimer) $interval.cancel(pollTimer);
  });
};

sp_widget.css:
.ocr-widget .panel {
  border-radius: 8px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.08);
  border: 1px solid #e0e0e0;
}

.ocr-widget .panel-heading {
  background: #1782c5;
  color: #fff;
  border-radius: 8px 8px 0 0;
  padding: 16px 20px;
}

.ocr-widget .panel-title {
  color: #fff;
  font-size: 16px;
  font-weight: 600;
}

.ocr-widget .panel-body {
  padding: 24px;
}

/* Upload Zone */
.upload-zone {
  border: 2px dashed #c0cdd6;
  border-radius: 8px;
  padding: 48px 24px;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s ease, background-color 0.2s ease;
  margin-bottom: 20px;
  background: #f8fbfd;
}

.upload-zone:hover,
.upload-zone.drag-over {
  border-color: #1782c5;
  background-color: #eef6fb;
}

.upload-icon {
  font-size: 40px;
  color: #9eb5c5;
  display: block;
  margin-bottom: 12px;
}

.upload-text {
  font-size: 15px;
  color: #4a5568;
  margin: 0 0 6px;
  font-weight: 500;
}

/* Processing State */
.processing-state {
  padding: 40px 20px;
}

.processing-state h4 {
  color: #1782c5;
  margin: 16px 0 8px;
  font-weight: 600;
}

.ocr-spinner {
  display: flex;
  justify-content: center;
  margin-bottom: 8px;
}

.spinner-ring {
  width: 52px;
  height: 52px;
  border: 5px solid #dde8f0;
  border-top-color: #1782c5;
  border-radius: 50%;
  animation: ocr-spin 0.85s linear infinite;
}

@keyframes ocr-spin {
  to { transform: rotate(360deg); }
}

/* Results Grid */
.result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
  margin: 16px 0 20px;
}

.result-card {
  background: #f7f9fb;
  border: 1px solid #e4eaf0;
  border-radius: 8px;
  padding: 14px 16px;
  transition: box-shadow 0.15s;
}

.result-card:hover {
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.result-card.highlight {
  border-color: #1782c5;
  background: #eef6fb;
  grid-column: 1 / -1;
}

.result-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #7a8fa0;
  margin-bottom: 6px;
}

.result-value {
  font-size: 17px;
  font-weight: 600;
  color: #1a2b3c;
  word-break: break-word;
}

.result-card.highlight .result-value {
  font-size: 20px;
  color: #1782c5;
}

/* Risk Badge */
.risk-badge {
  display: inline-block;
  padding: 3px 12px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
}

.risk-low    { background: #d4edda; color: #1a5c2e; }
.risk-medium { background: #fff3cd; color: #7d5c00; }
.risk-high   { background: #f8d7da; color: #7c1d23; }

/* AI Summary */
.summary-box {
  background: #f4f8fc;
  border-left: 4px solid #1782c5;
  border-radius: 0 8px 8px 0;
  padding: 16px 20px;
  margin-top: 4px;
}

.summary-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #1782c5;
  margin-bottom: 10px;
}

.summary-text {
  font-size: 14px;
  color: #3a4a5a;
  line-height: 1.7;
  margin: 0;
}
/* AI Summary Points */
.summary-points {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 4px;
}

.summary-point {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: #ffffff;
  border: 1px solid #ddeaf5;
  border-radius: 8px;
  padding: 10px 14px;
  transition: box-shadow 0.15s;
}

.summary-point:hover {
  box-shadow: 0 2px 8px rgba(23, 130, 197, 0.1);
  border-color: #1782c5;
}

.point-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  background: #1782c5;
  color: #ffffff;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 700;
  margin-top: 1px;
  flex-shrink: 0;
}

.point-text {
  font-size: 14px;
  color: #2d3f50;
  line-height: 1.6;
}

/* Color first point differently as company header */
.summary-point:first-child {
  background: #eef6fb;
  border-color: #1782c5;
}

.summary-point:first-child .point-text {
  font-weight: 600;
  color: #1782c5;
}

sp_widget.script:
(function() {

  // 🔥 FIX: Prevent error on initial load
  if (!input) {
    return;
  }

  gs.info("OCR Widget Hit | Action: " + input.action);

  // CREATE RECORD
  if (input.action === 'create_record') {
    try {
      var rec = new GlideRecord('x_birl3_clm_ocr_test');
      rec.initialize();

      var sysId = rec.insert();

      if (!sysId) {
        data.serverError = 'Failed to create record';
        return;
      }

      data.sysId = sysId;

    } catch (e) {
      data.serverError = e.message;
    }

    return;
  }

  // POLL RESULT
  if (input.action === 'poll') {

    if (!input.sysId) {
      data.pollError = 'No sysId provided';
      return;
    }

    var rec = new GlideRecord('x_birl3_clm_ocr_test');

    if (rec.get(input.sysId)) {

      var name = rec.getValue('name_of_company');

      if (name) {
        data.result = {
          number: rec.getValue('number'),
          name_of_company: name,
          rating: rec.getValue('rating'),
          risk_index: rec.getValue('risk_index'),
          credit_limit: rec.getValue('credit_limit'),
          total_current_liabilities: rec.getValue('total_current_liabilities'),
          total_non_current_liabilities: rec.getValue('total_non_current_liabilities'),
          total_equity: rec.getValue('total_equity'),
          total_equity_liabilities: rec.getValue('total_equity_liabilities'),
          ai_summary: rec.getValue('ai_summary')
        };
      }

    } else {
      data.pollError = 'Record not found';
    }

    return;
  }

})();
